<?php require 'config/functions.php';$pageTitle='Keranjang';$items=cart_products($pdo);$total=0;include 'partials/header.php';?><section class="container section"><h1 class="page-title">Keranjang Belanja</h1><?php if(!$items):?><div class="empty"><h2>Keranjang masih kosong</h2><p>Yuk temukan pakaian favoritmu.</p><a class="btn btn-dark" href="products.php">Mulai Belanja</a></div><?php else:?><div class="cart-layout"><div><?php foreach($items as $item):$subtotal=$item['price']*$item['quantity'];$total+=$subtotal;?><div class="cart-item"><img src="<?=e($item['image'])?>" alt="<?=e($item['name'])?>"><div class="cart-item-info"><h3><?=e($item['name'])?></h3><p><?=rupiah($item['price'])?></p><form method="post" action="cart_action.php" class="qty-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="update"><input type="number" name="quantity" min="0" max="<?=(int)$item['stock']?>" value="<?=(int)$item['quantity']?>"><button class="btn btn-outline">Update</button></form><form method="post" action="cart_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="remove"><button class="text-button">Hapus</button></form></div><strong><?=rupiah($subtotal)?></strong></div><?php endforeach;?></div><aside class="summary"><h2>Ringkasan Belanja</h2><div class="summary-row"><span>Subtotal</span><strong><?=rupiah($total)?></strong></div><p class="muted">Biaya pengiriman belum termasuk.</p><a class="btn btn-dark full" href="checkout.php">Lanjut Checkout →</a></aside></div><?php endif;?></section><?php include 'partials/footer.php';?>